/* Graph viewer for larpidarium.
 *
 * Adapted from taraxaplan graph.js, https://github.com/Karlord19/taraxaplan
 * Copyright (c) 2026 Karlord19, MIT License (see LICENSE-taraxaplan).
 *
 * Changes from the original: data comes from graph-data.js (generated by `larpidarium build`
 * or `larpidarium serve`), edges are computed in Rust, the DOM is built with textContent
 * instead of innerHTML, editing modals were replaced by forms that send edits to
 * `larpidarium serve` (which writes the TOML files), segments are drawn as areas, a details
 * panel and Czech/English labels are added, and node positions and line bends can be saved
 * as layout.toml.
 */
(() => {
  'use strict';

  const G = window.LARP_GRAPH;
  const EDIT = Boolean(window.LARP_EDIT);
  if (!G) {
    // `serve` could not read the game at all (a file is not valid TOML, game.toml is missing…).
    const box = document.createElement('div');
    box.className = 'problems';
    const h = document.createElement('h2');
    h.textContent = 'larpidarium: the game cannot be read / hru nelze načíst';
    box.append(h);
    for (const p of window.LARP_PROBLEMS || []) {
      const line = document.createElement('pre');
      line.textContent = p;
      box.append(line);
    }
    document.body.replaceChildren(box);
    pollForChanges();
    return;
  }
  const NODE_W = 200;
  const STORAGE_KEY = `larpidarium-layout:${G.title}`;

  const TEXT = {
    cs: {
      in: 'Potřebuje', uses: 'Spotřebuje', out: 'Dává', health: 'Stav hry', healthy: '✔ Bez problémů',
      endings: 'Dosažitelné konce', noEndings: 'Hra nemá žádný konec (ending = true).', outcomes: 'možných výsledků',
      brief: 'Pro hráče', orgText: 'Pro organizátory', stopped: 'simulace zastavena předčasně', owners: 'Postavy a místnosti', things: 'Předměty a informace',
      clearFilter: 'Zrušit filtr', exportLayout: 'Uložit layout.toml', resetLayout: 'Obnovit rozložení',
      light: 'Světlý režim', dark: 'Tmavý režim', unassigned: 'Bez vlastníka', action: 'Akce',
      decision: 'Rozhodnutí', options: 'Možnosti', starting: 'od začátku', ending: 'konec',
      item: 'předmět', info: 'informace', player: 'hráč', organizer: 'organizátor', npc: 'CP',
      room: 'místnost', close: 'Zavřít', sheet: 'list postavy',
      segments: 'Segmenty', noSegment: 'Bez segmentu', segment: 'Segment', crossing: 'přechod mezi segmenty',
      editing: 'Úpravy', newAction: '+ Akce', newDecision: '+ Rozhodnutí', newThing: '+ Předmět / info',
      newSegment: '+ Segment', saveLayout: 'Uložit rozložení do hry', edit: 'Upravit', remove: 'Smazat',
      save: 'Uložit', cancel: 'Zrušit', id: 'Id (název souboru)', title: 'Název', name: 'Název',
      owner: 'Kdo', add: '+ přidat…', option: 'Možnost', addOption: '+ Možnost', label: 'Popisek',
      color: 'Barva', category: 'Kategorie', kind: 'Druh', none: '—', saved: 'Uloženo',
      errors: 'chyb', warnings: 'varování', confirmDelete: 'Opravdu smazat „{x}“? Soubor bude odstraněn.',
      layoutSaved: 'Rozložení uloženo do layout.toml', idHelp: 'malá písmena bez diakritiky, číslice a pomlčky',
      editThing: 'Upravit předmět nebo informaci', editSegment: 'Upravit segment',
      briefHelp: 'hráči uvidí v listu postavy', textHelp: 'jen pro organizátory',
      hint: 'Tažení pozadí: posun. Kolečko: přiblížení. Tažení uzlu: přesun (Shift+klik vybere více). ' +
        'Shift+klik na čáru: ohyb, Shift+klik na ohyb: smazat. Klik na uzel: detail. ' +
        'Klik na postavu nebo předmět: zvýraznit jeho linku.',
    },
    en: {
      in: 'Needs', uses: 'Uses up', out: 'Gives', health: 'Game health', healthy: '✔ No problems',
      endings: 'Reachable endings', noEndings: 'The game has no ending (ending = true).', outcomes: 'possible outcomes',
      brief: 'For players', orgText: 'For organizers', stopped: 'simulation stopped early', owners: 'People and rooms', things: 'Items and info',
      clearFilter: 'Clear filter', exportLayout: 'Save layout.toml', resetLayout: 'Reset layout',
      light: 'Light mode', dark: 'Dark mode', unassigned: 'Unassigned', action: 'Action',
      decision: 'Decision', options: 'Options', starting: 'at start', ending: 'ending',
      item: 'item', info: 'info', player: 'player', organizer: 'organizer', npc: 'NPC',
      room: 'room', close: 'Close', sheet: 'character sheet',
      segments: 'Segments', noSegment: 'No segment', segment: 'Segment', crossing: 'crosses segments',
      editing: 'Editing', newAction: '+ Action', newDecision: '+ Decision', newThing: '+ Item / info',
      newSegment: '+ Segment', saveLayout: 'Save layout into the game', edit: 'Edit', remove: 'Delete',
      save: 'Save', cancel: 'Cancel', id: 'Id (file name)', title: 'Title', name: 'Name',
      owner: 'Who', add: '+ add…', option: 'Option', addOption: '+ Option', label: 'Label',
      color: 'Color', category: 'Category', kind: 'Kind', none: '—', saved: 'Saved',
      errors: 'errors', warnings: 'warnings', confirmDelete: 'Really delete “{x}”? The file will be removed.',
      layoutSaved: 'Layout saved to layout.toml', idHelp: 'lowercase ASCII letters, digits and dashes',
      editThing: 'Edit item or info', editSegment: 'Edit segment',
      briefHelp: 'players see this on their character sheet', textHelp: 'organizers only',
      hint: 'Drag background: pan. Wheel: zoom. Drag node: move (Shift+click selects several). ' +
        'Shift+click a line: add bend, Shift+click a bend: remove. Click node: details. ' +
        'Click a person or item: highlight its storyline.',
    },
  };
  const t = TEXT[G.language] || TEXT.en;

  const owners = new Map(G.owners.map((o) => [o.id, o]));
  const segments = new Map(G.segments.map((s) => [s.id, s]));
  /** Segment a node is drawn in: unknown segment ids count as "no segment", like in the layout. */
  const segKey = (n) => (segments.has(n.segment) ? n.segment : '');
  const segColor = (s) => s?.color || '#888888';
  const things = new Map(G.things.map((x) => [x.id, x]));
  const nodes = G.nodes.map((n) => ({ ...n }));
  const byId = new Map(nodes.map((n) => [n.id, n]));
  let knees = structuredClone(G.knees || {});

  let filter = null; // { kind: 'owner' | 'thing' | 'segment', id }
  const selected = new Set();
  let detailsId = null;

  // ---------- persistence (per browser, optional) ----------
  const storage = {
    load() {
      try { return JSON.parse(localStorage.getItem(STORAGE_KEY) || 'null'); } catch { return null; }
    },
    save() {
      const pos = Object.fromEntries(nodes.map((n) => [n.id, { x: n.x, y: n.y }]));
      try { localStorage.setItem(STORAGE_KEY, JSON.stringify({ pos, knees })); } catch { /* private mode */ }
    },
    clear() {
      try { localStorage.removeItem(STORAGE_KEY); } catch { /* private mode */ }
    },
  };
  const saved = storage.load();
  if (saved) {
    for (const n of nodes) if (saved.pos?.[n.id]) Object.assign(n, saved.pos[n.id]);
    if (saved.knees) knees = saved.knees;
  }

  // ---------- helpers ----------
  const $ = (id) => document.getElementById(id);
  const el = (tag, cls, text) => {
    const e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text !== undefined && text !== null) e.textContent = text;
    return e;
  };
  const svgEl = (tag, attrs) => {
    const e = document.createElementNS('http://www.w3.org/2000/svg', tag);
    for (const [k, v] of Object.entries(attrs || {})) e.setAttribute(k, v);
    return e;
  };
  const ownerName = (id) => owners.get(id)?.name ?? id;
  const thingName = (id) => things.get(id)?.name ?? id;
  const allThings = (n) => [...n.needs, ...n.uses, ...n.gives,
    ...n.options.flatMap((o) => [...o.needs, ...o.uses, ...o.gives])];
  const flagged = new Set(G.findings.map((f) => f.node).filter(Boolean));

  function ownerGradient(ids) {
    if (!ids.length) return '#444444';
    const colors = [...ids].sort((a, b) => ownerName(a).localeCompare(ownerName(b)))
      .map((id) => owners.get(id)?.color ?? '#888888');
    if (colors.length === 1) return colors[0];
    const pct = 100 / colors.length;
    return `linear-gradient(to right, ${colors.map((c, i) => `${c} ${i * pct}%, ${c} ${(i + 1) * pct}%`).join(', ')})`;
  }

  function thingSpan(id) {
    const x = things.get(id);
    const s = el('span', 'thing', thingName(id));
    if (x?.color) s.style.borderBottom = `2px solid ${x.color}`;
    if (x?.text) s.title = x.text;
    return s;
  }

  function thingLine(label, ids) {
    if (!ids.length) return null;
    const d = el('div', 'node-req');
    d.append(`${label}: `);
    ids.forEach((id, i) => { if (i) d.append(', '); d.append(thingSpan(id)); });
    return d;
  }

  function nodeMatches(n) {
    if (!filter) return true;
    if (filter.kind === 'owner') return n.owners.includes(filter.id);
    if (filter.kind === 'segment') return segKey(n) === filter.id;
    return allThings(n).includes(filter.id);
  }

  function edgeMatches(e) {
    if (!filter) return true;
    if (filter.kind === 'thing') return e.items.includes(filter.id);
    if (filter.kind === 'segment') return nodeMatches(byId.get(e.from)) || nodeMatches(byId.get(e.to));
    return nodeMatches(byId.get(e.from)) && nodeMatches(byId.get(e.to));
  }

  // ---------- nodes ----------
  function renderNodes() {
    const container = $('nodes-container');
    container.replaceChildren();
    for (const n of nodes) {
      const node = el('div', `node ${n.kind}`);
      node.id = `node-${n.id}`;
      if (selected.has(n.id)) node.classList.add('selected');
      if (!nodeMatches(n)) node.classList.add('faded');
      if (flagged.has(n.id)) node.classList.add('flagged');
      node.style.left = `${n.x}px`;
      node.style.top = `${n.y}px`;

      const bar = el('div', 'node-color-bar');
      bar.style.background = ownerGradient(n.owners);
      const core = el('div', 'node-core');
      const names = n.owners.map(ownerName).sort((a, b) => a.localeCompare(b)).join(', ');
      core.append(el('div', 'node-owner', names || t.unassigned), el('div', 'node-desc', n.title));
      const lines = [thingLine(t.in, n.needs), thingLine(t.uses, n.uses), thingLine(t.out, n.gives)].filter(Boolean);
      core.append(...lines);
      node.append(bar, core);

      if (n.kind === 'decision') {
        const opts = el('div', 'node-decision-opts');
        n.options.forEach((o, i) => {
          const row = el('div', 'node-opt-row');
          row.dataset.opt = String(i);
          row.append(el('div', 'opt-label', `▶ ${o.label}`));
          const optLines = [thingLine(t.in, o.needs), thingLine(t.uses, o.uses), thingLine(t.out, o.gives)]
            .filter(Boolean);
          row.append(...optLines);
          opts.append(row);
        });
        node.append(opts);
      }

      node.addEventListener('mousedown', (e) => {
        if (e.button !== 0) return;
        if (e.shiftKey) {
          if (selected.has(n.id)) selected.delete(n.id); else selected.add(n.id);
        } else if (!selected.has(n.id)) {
          selected.clear();
          selected.add(n.id);
        }
        dragging = { type: 'node', id: n.id, moved: false };
        e.stopPropagation();
        renderNodes();
      });
      container.append(node);
    }
  }

  // ---------- connections ----------
  function portY(nodeId, port, fallback) {
    if (port === null || port === undefined) return fallback;
    const row = document.querySelector(`#node-${CSS.escape(nodeId)} .node-opt-row[data-opt="${port}"]`);
    return row ? row.offsetTop + row.offsetHeight / 2 : fallback;
  }

  function distanceToSegment(p, v, w) {
    const l2 = (w.x - v.x) ** 2 + (w.y - v.y) ** 2;
    if (l2 === 0) return Math.hypot(p.x - v.x, p.y - v.y);
    const k = Math.max(0, Math.min(1, ((p.x - v.x) * (w.x - v.x) + (p.y - v.y) * (w.y - v.y)) / l2));
    return Math.hypot(p.x - (v.x + k * (w.x - v.x)), p.y - (v.y + k * (w.y - v.y)));
  }

  function drawLine(svg, edge, start, end) {
    const bends = knees[edge.id] || [];
    const points = [start, ...bends, end];
    const d = points.map((p, i) => `${i ? 'L' : 'M'} ${p.x} ${p.y}`).join(' ');
    const group = svgEl('g');
    if (!edgeMatches(edge)) group.classList.add('faded');
    if (edge.cross) group.classList.add('cross');

    group.append(svgEl('path', { d, class: 'connection-path', 'marker-end': 'url(#arrowhead)' }));
    const hit = svgEl('path', { d, class: 'connection-hitbox' });
    const tip = svgEl('title');
    tip.textContent = edge.items.map(thingName).join(', ') + (edge.cross ? ` (${t.crossing})` : '');
    hit.append(tip);
    hit.addEventListener('mousedown', (e) => {
      if (e.button !== 0 || !e.shiftKey) return;
      e.preventDefault();
      e.stopPropagation();
      const click = toGraph(e);
      let best = 0;
      let bestDist = Infinity;
      for (let i = 0; i < points.length - 1; i++) {
        const dist = distanceToSegment(click, points[i], points[i + 1]);
        if (dist < bestDist) { bestDist = dist; best = i; }
      }
      knees[edge.id] = [...bends];
      knees[edge.id].splice(best, 0, click);
      storage.save();
      renderConnections();
    });
    group.append(hit);

    bends.forEach((k, index) => {
      const knee = svgEl('g');
      knee.style.cursor = 'grab';
      knee.append(svgEl('circle', { cx: k.x, cy: k.y, r: 4, class: 'knee' }));
      const area = svgEl('circle', { cx: k.x, cy: k.y, r: 12, fill: 'transparent' });
      area.style.pointerEvents = 'fill';
      knee.append(area);
      knee.addEventListener('mousedown', (e) => {
        if (e.button !== 0) return;
        e.stopPropagation();
        e.preventDefault();
        if (e.shiftKey) {
          knees[edge.id].splice(index, 1);
          if (!knees[edge.id].length) delete knees[edge.id];
          storage.save();
          renderConnections();
        } else {
          dragging = { type: 'knee', edge: edge.id, index, moved: false };
        }
      });
      group.append(knee);
    });
    svg.append(group);
  }

  function renderConnections() {
    const svg = $('connections-canvas');
    svg.replaceChildren();
    const defs = svgEl('defs');
    const marker = svgEl('marker', {
      id: 'arrowhead', markerWidth: 10, markerHeight: 7, refX: 9, refY: 3.5, orient: 'auto',
    });
    marker.append(svgEl('polygon', { points: '0 0, 10 3.5, 0 7', class: 'arrowhead' }));
    defs.append(marker);
    svg.append(defs);

    for (const e of G.edges) {
      const from = byId.get(e.from);
      const to = byId.get(e.to);
      if (!from || !to) continue;
      const start = { x: from.x + NODE_W, y: from.y + portY(from.id, e.from_port, 40) };
      const end = { x: to.x - 5, y: to.y + portY(to.id, e.to_port, 40) };
      drawLine(svg, e, start, end);
    }
  }

  // ---------- segments ----------
  /** Bounding box of the nodes of one segment ('' = nodes without a segment). */
  function segmentBox(id) {
    let minX = Infinity; let minY = Infinity; let maxX = -Infinity; let maxY = -Infinity;
    for (const n of nodes) {
      if (segKey(n) !== id) continue;
      const h = $(`node-${n.id}`)?.offsetHeight ?? 100;
      minX = Math.min(minX, n.x); minY = Math.min(minY, n.y);
      maxX = Math.max(maxX, n.x + NODE_W); maxY = Math.max(maxY, n.y + h);
    }
    return minX === Infinity ? null : { minX, minY, maxX, maxY };
  }

  /** Segments in display order, plus a pseudo-segment for unsorted nodes when there are any. */
  function segmentRows() {
    const rows = G.segments.map((s) => ({ ...s, color: segColor(s), count: nodes.filter((n) => segKey(n) === s.id).length }));
    const loose = nodes.filter((n) => segKey(n) === '').length;
    if (rows.length && loose) rows.push({ id: '', name: t.noSegment, color: '#888888', text: '', count: loose });
    return rows;
  }

  function renderSegments() {
    const layerEl = $('segments-layer');
    layerEl.replaceChildren();
    if (!G.segments.length) return;
    const PAD = 28;
    for (const s of segmentRows()) {
      const box = segmentBox(s.id);
      if (!box) continue;
      const area = el('div', 'segment-area');
      if (filter?.kind === 'segment' && filter.id !== s.id) area.classList.add('faded');
      Object.assign(area.style, {
        left: `${box.minX - PAD}px`, top: `${box.minY - PAD}px`,
        width: `${box.maxX - box.minX + 2 * PAD}px`, height: `${box.maxY - box.minY + 2 * PAD}px`,
        background: `${s.color}1f`, borderColor: `${s.color}88`,
      });
      const title = el('div', 'segment-title', s.name);
      title.style.color = s.color;
      if (s.text) title.title = s.text;
      title.addEventListener('mousedown', (e) => e.stopPropagation());
      title.addEventListener('click', () => focusSegment(s.id));
      area.append(title);
      layerEl.append(area);
    }
  }

  function focusSegment(id) {
    const same = filter?.kind === 'segment' && filter.id === id;
    setFilter({ kind: 'segment', id });
    if (!same) fitTo(segmentBox(id));
  }

  function renderSegmentList() {
    const section = $('segment-section');
    const list = $('segment-list');
    list.replaceChildren();
    section.classList.toggle('hidden', !G.segments.length && !EDIT);
    for (const s of segmentRows()) {
      const li = el('li');
      if (filter?.kind === 'segment' && filter.id === s.id) li.classList.add('active');
      const dot = el('span', 'dot');
      dot.style.background = s.color;
      dot.style.borderRadius = '2px';
      li.append(dot, el('span', null, s.name), el('span', 'tag', String(s.count)));
      if (s.text) li.title = s.text;
      if (EDIT && s.id) li.append(editIcon(() => segmentForm(s)));
      li.addEventListener('click', () => focusSegment(s.id));
      list.append(li);
    }
  }

  function renderAll() {
    renderNodes();
    renderSegments();
    renderConnections();
  }

  // ---------- details panel ----------
  function showDetails(id) {
    detailsId = id;
    const n = byId.get(id);
    const box = $('details');
    box.replaceChildren();
    if (!n) { box.classList.add('hidden'); return; }

    const close = el('button', 'close', '×');
    close.setAttribute('aria-label', t.close);
    close.addEventListener('click', () => { detailsId = null; box.classList.add('hidden'); });
    box.append(close, el('div', 'kind', n.kind === 'decision' ? t.decision : t.action), el('h4', null, n.title));
    if (n.segment) {
      const seg = el('div', 'segment-chip', segments.get(n.segment)?.name ?? n.segment);
      seg.style.borderColor = segColor(segments.get(n.segment));
      box.append(seg);
    }

    if (n.owners.length) {
      const who = el('div');
      n.owners.forEach((oid) => {
        const chip = el('span', 'tag', ownerName(oid));
        chip.style.marginRight = '8px';
        chip.style.borderBottom = `2px solid ${owners.get(oid)?.color ?? '#888'}`;
        who.append(chip);
      });
      box.append(who);
    }
    if (n.brief) box.append(el('div', 'label', t.brief), el('div', 'brief', n.brief.trim()));
    if (n.text) box.append(el('div', 'label', t.orgText), el('div', 'text', n.text.trim()));

    const list = (label, ids) => {
      if (!ids.length) return;
      box.append(el('strong', null, label));
      const ul = el('ul');
      for (const id of ids) {
        const li = el('li');
        li.append(thingSpan(id));
        const text = things.get(id)?.text;
        if (text) { li.append(el('br')); li.append(el('span', 'thing-text', text)); }
        ul.append(li);
      }
      box.append(ul);
    };
    list(t.in, n.needs);
    list(t.uses, n.uses);
    list(t.out, n.gives);
    for (const o of n.options) {
      box.append(el('div', 'opt-label', `▶ ${o.label}`));
      list(t.in, o.needs);
      list(t.uses, o.uses);
      list(t.out, o.gives);
    }
    if (EDIT) {
      const row = el('div', 'edit-row');
      const editBtn = el('button', null, t.edit);
      editBtn.addEventListener('click', () => nodeForm(n.kind, n));
      const delBtn = el('button', 'danger', t.remove);
      delBtn.addEventListener('click', () => deleteNode(n));
      row.append(editBtn, delBtn);
      box.append(row);
    }
    box.classList.remove('hidden');
  }

  // ---------- legend & filter ----------
  function setFilter(next) {
    filter = filter && next && filter.kind === next.kind && filter.id === next.id ? null : next;
    $('btn-clear-filter').classList.toggle('hidden', !filter);
    renderLegend();
    renderSegmentList();
    renderAll();
  }

  function renderLegend() {
    const ownerList = $('owner-list');
    ownerList.replaceChildren();
    for (const o of G.owners) {
      const li = el('li');
      if (filter?.kind === 'owner' && filter.id === o.id) li.classList.add('active');
      const dot = el('span', 'dot');
      dot.style.background = o.color;
      li.append(dot, el('span', null, o.name), el('span', 'tag', t[o.role ?? 'room']));
      if (o.role === 'player') {
        const link = el('a', 'sheet-link', '📄');
        link.href = `players/${encodeURIComponent(o.id)}.html`;
        link.title = t.sheet;
        link.addEventListener('click', (e) => e.stopPropagation());
        li.append(link);
      }
      li.addEventListener('click', () => setFilter({ kind: 'owner', id: o.id }));
      ownerList.append(li);
    }
    const thingList = $('thing-list');
    thingList.replaceChildren();
    for (const x of G.things) {
      const li = el('li');
      if (filter?.kind === 'thing' && filter.id === x.id) li.classList.add('active');
      const dot = el('span', 'dot');
      dot.style.background = x.color ?? 'transparent';
      dot.style.border = '1px solid var(--line-color)';
      if (x.kind === 'info') dot.style.borderRadius = '2px';
      const tags = [t[x.kind], x.starting ? t.starting : null, x.ending ? t.ending : null].filter(Boolean);
      li.append(dot, el('span', null, x.name), el('span', 'tag', tags.join(' · ')));
      if (x.text) li.title = x.text;
      if (EDIT) li.append(editIcon(() => thingForm(x)));
      li.addEventListener('click', () => setFilter({ kind: 'thing', id: x.id }));
      thingList.append(li);
    }
  }

  // ---------- game health ----------
  function renderHealth() {
    const box = $('health');
    box.replaceChildren();
    if (!G.findings.length) box.append(el('div', 'ok', t.healthy));
    for (const f of G.findings) {
      const item = el('div', `finding ${f.severity}`);
      item.append(el('div', null, `${f.severity === 'error' ? '✖' : '⚠'} ${f.message}`));
      if (f.help) item.append(el('div', 'help', f.help));
      item.title = f.file;
      if (f.node) {
        item.addEventListener('click', () => {
          selected.clear();
          selected.add(f.node);
          renderNodes();
          showDetails(f.node);
        });
      }
      box.append(item);
    }
    const hasEndings = G.things.some((x) => x.ending);
    if (!hasEndings) { box.append(el('div', 'help', t.noEndings)); return; }
    const head = `${t.endings} (${G.end_states} ${t.outcomes}${G.truncated ? `, ${t.stopped}` : ''})`;
    box.append(el('div', 'label', head));
    for (const e of G.endings) {
      const row = el('div', 'ending');
      row.append(el('div', null, thingName(e.id)), el('div', 'route', e.route.join(' → ') || '—'));
      row.addEventListener('click', () => setFilter({ kind: 'thing', id: e.id }));
      box.append(row);
    }
  }

  // ---------- pan, zoom, drag ----------
  let scale = 1;
  let panX = 0;
  let panY = 0;
  let dragging = null;
  let panning = false;
  const layer = $('graph-transform-layer');
  const workspace = $('workspace-graph');

  const updateTransform = () => { layer.style.transform = `translate(${panX}px, ${panY}px) scale(${scale})`; };
  const toGraph = (e) => {
    const r = layer.getBoundingClientRect();
    return { x: (e.clientX - r.left) / scale, y: (e.clientY - r.top) / scale };
  };

  workspace.addEventListener('mousedown', (e) => {
    if (e.target === workspace || e.target.tagName === 'svg') {
      panning = true;
      workspace.style.cursor = 'grabbing';
      if (!e.shiftKey && selected.size) { selected.clear(); renderNodes(); }
    }
  });

  window.addEventListener('mousemove', (e) => {
    if (panning) { panX += e.movementX; panY += e.movementY; updateTransform(); return; }
    if (!dragging) return;
    dragging.moved = true;
    const dx = e.movementX / scale;
    const dy = e.movementY / scale;
    if (dragging.type === 'node') {
      const ids = selected.has(dragging.id) ? [...selected] : [dragging.id];
      for (const id of ids) { const n = byId.get(id); n.x += dx; n.y += dy; }
      renderAll();
    } else {
      const k = knees[dragging.edge][dragging.index];
      k.x += dx;
      k.y += dy;
      renderConnections();
    }
  });

  window.addEventListener('mouseup', () => {
    if (dragging?.moved) storage.save();
    else if (dragging?.type === 'node') showDetails(dragging.id);
    dragging = null;
    panning = false;
    workspace.style.cursor = 'default';
  });

  workspace.addEventListener('wheel', (e) => {
    e.preventDefault();
    const zoom = Math.exp((e.deltaY < 0 ? 1 : -1) * 0.1);
    const r = layer.getBoundingClientRect();
    scale *= zoom;
    panX -= (e.clientX - r.left) * (zoom - 1);
    panY -= (e.clientY - r.top) * (zoom - 1);
    updateTransform();
  }, { passive: false });

  function centerAndFit() {
    if (!nodes.length) return;
    let minX = Infinity; let minY = Infinity; let maxX = -Infinity; let maxY = -Infinity;
    for (const n of nodes) {
      const h = $(`node-${n.id}`)?.offsetHeight ?? 100;
      minX = Math.min(minX, n.x); minY = Math.min(minY, n.y);
      maxX = Math.max(maxX, n.x + NODE_W); maxY = Math.max(maxY, n.y + h);
    }
    fitTo({ minX, minY: minY - (G.segments.length ? 50 : 0), maxX, maxY });
  }

  function fitTo(box) {
    if (!box) return;
    const { minX, minY, maxX, maxY } = box;
    const w = maxX - minX + 80;
    const h = maxY - minY + 80;
    scale = Math.min(1.2, Math.min(workspace.clientWidth / w, workspace.clientHeight / h) * 0.95);
    panX = (workspace.clientWidth - (maxX - minX) * scale) / 2 - minX * scale;
    panY = (workspace.clientHeight - (maxY - minY) * scale) / 2 - minY * scale;
    updateTransform();
  }

  // ---------- layout export ----------
  /**
   * layout.toml text. With `onlyMoved`, only nodes whose position differs from the one the page
   * was generated with: the server merges them into the existing file, and the other nodes keep
   * following the automatic layout.
   */
  function layoutToml(onlyMoved) {
    const r = (v) => Math.round(v);
    const out = [
      '# Saved from the larpidarium graph view.',
      '# Put this file into the game folder (next to game.toml) and run `larpidarium build` again.',
      '',
    ];
    const moved = (n) => {
      const o = byIdOriginal.get(n.id);
      return !o || r(o.x) !== r(n.x) || r(o.y) !== r(n.y);
    };
    for (const n of [...nodes].sort((a, b) => a.id.localeCompare(b.id))) {
      if (onlyMoved && !moved(n)) continue;
      out.push(`[node.${n.id}]`, `x = ${r(n.x)}`, `y = ${r(n.y)}`, '');
    }
    const edges = Object.keys(knees).filter((k) => knees[k].length).sort();
    if (edges.length) {
      out.push('[knees]');
      for (const k of edges) {
        const pts = knees[k].map((p) => `{ x = ${r(p.x)}, y = ${r(p.y)} }`).join(', ');
        out.push(`"${k}" = [${pts}]`);
      }
      out.push('');
    }
    return out.join('\n');
  }

  $('btn-export-layout').addEventListener('click', () => {
    const blob = new Blob([layoutToml()], { type: 'application/toml' });
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'layout.toml';
    a.click();
    URL.revokeObjectURL(a.href);
  });

  $('btn-reset-layout').addEventListener('click', () => {
    storage.clear();
    for (const n of nodes) Object.assign(n, { x: byIdOriginal.get(n.id).x, y: byIdOriginal.get(n.id).y });
    knees = structuredClone(G.knees || {});
    renderAll();
    centerAndFit();
  });
  const byIdOriginal = new Map(G.nodes.map((n) => [n.id, n]));

  // ---------- editing (only with `larpidarium serve`) ----------
  function editIcon(onClick) {
    const b = el('button', 'edit-icon', '✎');
    b.title = t.edit;
    b.addEventListener('click', (e) => { e.stopPropagation(); onClick(); });
    return b;
  }

  function toast(message) {
    const box = $('toast');
    box.textContent = message;
    box.classList.remove('hidden');
    clearTimeout(toast.timer);
    toast.timer = setTimeout(() => box.classList.add('hidden'), 4000);
  }

  async function post(path, body) {
    const res = await fetch(path, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Larpidarium': '1' },
      body: JSON.stringify(body),
    });
    let data = null;
    try { data = await res.json(); } catch { /* plain-text error */ }
    if (!res.ok || !data?.ok) throw new Error(data?.error ?? `${res.status} ${res.statusText}`);
    return data;
  }

  /** After a successful write: reload, and show the result once the page is back. */
  function reloadWith(message) {
    try { sessionStorage.setItem('larpidarium-toast', message); } catch { /* private mode */ }
    location.reload();
  }
  const summary = (d) => `${t.saved} · ${d.errors} ${t.errors}, ${d.warnings} ${t.warnings}`;

  const slug = (s) => s.normalize('NFD').replace(/[̀-ͯ]/g, '').toLowerCase()
    .replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 64);

  /** A multi-select made of removable chips and a dropdown of the remaining choices. */
  function picker(choices, chosen) {
    const value = [...chosen];
    const wrap = el('div', 'picker');
    const render = () => {
      wrap.replaceChildren();
      for (const id of value) {
        const chip = el('span', 'chip', choices.find((c) => c.id === id)?.name ?? id);
        const x = el('button', 'chip-x', '×');
        x.type = 'button';
        x.addEventListener('click', () => { value.splice(value.indexOf(id), 1); render(); });
        chip.append(x);
        wrap.append(chip);
      }
      const select = el('select');
      select.append(new Option(t.add, ''));
      for (const c of choices) if (!value.includes(c.id)) select.append(new Option(c.label ?? c.name, c.id));
      select.addEventListener('change', () => { if (select.value) { value.push(select.value); render(); } });
      wrap.append(select);
    };
    render();
    return { el: wrap, value: () => [...value] };
  }

  const ownerChoices = () => G.owners.map((o) => ({ id: o.id, name: o.name, label: `${o.name} (${t[o.role ?? 'room']})` }));
  const thingChoices = () => G.things.map((x) => ({ id: x.id, name: x.name, label: `${x.name} (${t[x.kind]})` }));

  function field(form, label, input, help) {
    const row = el('label', 'field');
    row.append(el('span', 'field-label', label), input);
    if (help) row.append(el('span', 'field-help', help));
    form.append(row);
    return input;
  }
  function textInput(value, multiline) {
    const i = el(multiline ? 'textarea' : 'input');
    i.value = value ?? '';
    if (multiline) i.rows = 3;
    return i;
  }
  function selectInput(choices, value) {
    const s = el('select');
    s.append(new Option(t.none, ''));
    for (const c of choices) s.append(new Option(c.name, c.id));
    s.value = value ?? '';
    return s;
  }

  /**
   * Opens the editor dialog. `build(form)` adds fields and returns a function producing the
   * request body; `path` is the API endpoint.
   */
  function openEditor(heading, path, build) {
    const dialog = $('editor');
    const form = $('editor-form');
    form.replaceChildren(el('h3', null, heading));
    const collect = build(form);
    const error = el('div', 'form-error hidden');
    const buttons = el('div', 'form-buttons');
    const cancel = el('button', null, t.cancel);
    cancel.type = 'button';
    cancel.addEventListener('click', () => dialog.close());
    const save = el('button', 'primary', t.save);
    save.type = 'submit';
    buttons.append(cancel, save);
    form.append(error, buttons);
    form.onsubmit = async (e) => {
      e.preventDefault();
      save.disabled = true;
      try {
        reloadWith(summary(await post(path, collect())));
      } catch (err) {
        error.textContent = err.message;
        error.classList.remove('hidden');
        save.disabled = false;
      }
    };
    dialog.showModal();
  }

  /** Id field that follows the title until the user types an id of their own. */
  function idField(form, existing, source) {
    const input = field(form, t.id, textInput(existing ?? ''), t.idHelp);
    if (existing) { input.readOnly = true; return input; }
    let touched = false;
    input.addEventListener('input', () => { touched = true; });
    source.addEventListener('input', () => { if (!touched) input.value = slug(source.value); });
    return input;
  }

  function nodeForm(kind, n) {
    const create = !n;
    openEditor(create ? (kind === 'decision' ? t.newDecision : t.newAction) : `${t.edit}: ${n.title}`, '/api/node', (form) => {
      const title = textInput(n?.title);
      field(form, t.title, title);
      const id = idField(form, n?.id, title);
      const kindSel = el('select');
      kindSel.append(new Option(t.action, 'action'), new Option(t.decision, 'decision'));
      kindSel.value = n?.kind ?? kind;
      field(form, t.kind, kindSel);
      const who = picker(ownerChoices(), n?.owners ?? []);
      field(form, t.owner, who.el);
      const segDefault = n?.segment ?? (filter?.kind === 'segment' ? filter.id : '');
      // Keep an unknown segment id selectable, so saving does not silently drop it.
      const segChoices = segDefault && !segments.has(segDefault)
        ? [...G.segments, { id: segDefault, name: `${segDefault} (?)` }] : G.segments;
      const seg = selectInput(segChoices, segDefault);
      field(form, t.segment, seg);

      const actionBox = el('div', 'kind-box');
      const needs = picker(thingChoices(), n?.needs ?? []);
      const uses = picker(thingChoices(), n?.uses ?? []);
      const gives = picker(thingChoices(), n?.gives ?? []);
      field(actionBox, t.in, needs.el);
      field(actionBox, t.uses, uses.el);
      field(actionBox, t.out, gives.el);

      const decisionBox = el('div', 'kind-box');
      const optionList = el('div', 'option-list');
      const optionEditors = [];
      const addOption = (o) => {
        const box = el('fieldset', 'option-box');
        box.append(el('legend', null, t.option));
        const label = textInput(o?.label);
        field(box, t.label, label);
        const on = picker(thingChoices(), o?.needs ?? []);
        const ou = picker(thingChoices(), o?.uses ?? []);
        const og = picker(thingChoices(), o?.gives ?? []);
        field(box, t.in, on.el);
        field(box, t.uses, ou.el);
        field(box, t.out, og.el);
        const remove = el('button', 'danger small', t.remove);
        remove.type = 'button';
        const entry = { label, on, ou, og };
        remove.addEventListener('click', () => { box.remove(); optionEditors.splice(optionEditors.indexOf(entry), 1); });
        box.append(remove);
        optionEditors.push(entry);
        optionList.append(box);
      };
      (n?.options?.length ? n.options : [null, null]).forEach(addOption);
      const add = el('button', 'small', t.addOption);
      add.type = 'button';
      add.addEventListener('click', () => addOption(null));
      decisionBox.append(optionList, add);
      form.append(actionBox, decisionBox);

      const showKind = () => {
        actionBox.classList.toggle('hidden', kindSel.value !== 'action');
        decisionBox.classList.toggle('hidden', kindSel.value !== 'decision');
      };
      kindSel.addEventListener('change', showKind);
      showKind();

      const brief = field(form, t.brief, textInput(n?.brief, true), t.briefHelp);
      const text = field(form, t.orgText, textInput(n?.text, true), t.textHelp);
      return () => ({
        create, id: id.value.trim(), kind: kindSel.value, title: title.value, owners: who.value(),
        segment: seg.value, needs: needs.value(), uses: uses.value(), gives: gives.value(),
        brief: brief.value, text: text.value,
        options: kindSel.value === 'decision'
          ? optionEditors.map((o) => ({ label: o.label.value, needs: o.on.value(), uses: o.ou.value(), gives: o.og.value() }))
          : [],
      });
    });
  }

  function thingForm(x) {
    const create = !x;
    openEditor(create ? t.newThing : `${t.editThing}: ${x.name}`, '/api/thing', (form) => {
      const kindSel = el('select');
      kindSel.append(new Option(t.item, 'item'), new Option(t.info, 'info'));
      kindSel.value = x?.kind ?? 'item';
      kindSel.disabled = !create;
      field(form, t.kind, kindSel);
      const name = textInput(x?.name);
      field(form, t.name, name);
      const id = idField(form, x?.id, name);
      const cats = G.categories.map((c) => ({ id: c, name: c }));
      const cat = selectInput(cats, x?.category);
      const catRow = field(form, t.category, cat);
      const who = picker(ownerChoices(), x?.owners ?? []);
      field(form, t.owner, who.el);
      const flag = (label, on) => {
        const c = el('input');
        c.type = 'checkbox';
        c.checked = Boolean(on);
        field(form, label, c);
        return c;
      };
      const starting = flag(t.starting, x?.starting);
      const ending = flag(t.ending, x?.ending);
      const showKind = () => {
        catRow.parentElement.classList.toggle('hidden', kindSel.value !== 'item');
        ending.parentElement.classList.toggle('hidden', kindSel.value !== 'info');
      };
      kindSel.addEventListener('change', showKind);
      showKind();
      const text = field(form, t.orgText, textInput(x?.text, true));
      return () => ({
        create, kind: kindSel.value, id: id.value.trim(), name: name.value,
        category: kindSel.value === 'item' ? cat.value : '', owners: who.value(),
        starting: starting.checked, ending: kindSel.value === 'info' && ending.checked, text: text.value,
      });
    });
  }

  function segmentForm(s) {
    const create = !s;
    openEditor(create ? t.newSegment : `${t.editSegment}: ${s.name}`, '/api/segment', (form) => {
      const name = textInput(s?.name);
      field(form, t.name, name);
      const id = idField(form, s?.id, name);
      const color = el('input');
      color.type = 'color';
      color.value = s?.color || '#5b8def';
      // A segment without a color stays without one unless the user picks a color.
      let picked = create || Boolean(s?.color);
      color.addEventListener('input', () => { picked = true; });
      field(form, t.color, color);
      const text = field(form, t.orgText, textInput(s?.text, true));
      return () => ({ create, id: id.value.trim(), name: name.value, color: picked ? color.value : '', text: text.value });
    });
  }

  async function deleteNode(n) {
    if (!confirm(t.confirmDelete.replace('{x}', n.title))) return;
    try {
      const result = await post('/api/node/delete', { id: n.id });
      nodes.splice(nodes.indexOf(n), 1);
      storage.save(); // forget the deleted node's position in this browser
      reloadWith(summary(result));
    } catch (err) {
      toast(err.message);
    }
  }

  /** Live reload: when the game files change (in the browser or in a text editor), reload. */
  function pollForChanges() {
    let known = null;
    setInterval(async () => {
      if (document.querySelector('dialog[open]')) return;
      try {
        const { version } = await (await fetch('/api/version')).json();
        if (known && version !== known) location.reload();
        known = version;
      } catch { /* server stopped; keep the page */ }
    }, 1500);
  }

  if (EDIT) {
    $('edit-tools').classList.remove('hidden');
    $('btn-new-action').addEventListener('click', () => nodeForm('action', null));
    $('btn-new-decision').addEventListener('click', () => nodeForm('decision', null));
    $('btn-new-thing').addEventListener('click', () => thingForm(null));
    $('btn-new-segment').addEventListener('click', () => segmentForm(null));
    $('btn-save-layout').addEventListener('click', async () => {
      try {
        await post('/api/layout', { text: layoutToml(true) });
        storage.clear(); // positions now live in the game folder
        reloadWith(t.layoutSaved);
      } catch (err) {
        toast(err.message);
      }
    });
    try {
      const message = sessionStorage.getItem('larpidarium-toast');
      if (message) { sessionStorage.removeItem('larpidarium-toast'); setTimeout(() => toast(message), 300); }
    } catch { /* private mode */ }
    pollForChanges();
  }

  // ---------- chrome ----------
  function setTheme(theme) {
    document.documentElement.dataset.theme = theme;
    try { localStorage.setItem('larpidarium-theme', theme); } catch { /* private mode */ }
    $('theme-toggle').textContent = theme === 'light' ? t.dark : t.light;
  }
  let theme = 'dark';
  try { theme = localStorage.getItem('larpidarium-theme') || 'dark'; } catch { /* private mode */ }
  setTheme(theme);
  $('theme-toggle').addEventListener('click', () => setTheme(document.documentElement.dataset.theme === 'dark' ? 'light' : 'dark'));
  $('toggle-sidebar').addEventListener('click', () => $('sidebar').classList.toggle('collapsed'));
  $('btn-clear-filter').addEventListener('click', () => setFilter(null));
  $('btn-zoom-in').addEventListener('click', () => { scale *= 1.2; updateTransform(); });
  $('btn-zoom-out').addEventListener('click', () => { scale *= 0.8; updateTransform(); });
  $('btn-center-fit').addEventListener('click', centerAndFit);

  document.documentElement.lang = G.language;
  document.title = `${G.title} · larpidarium`;
  $('game-title').textContent = G.title;
  for (const e of document.querySelectorAll('[data-i18n]')) e.textContent = t[e.dataset.i18n];

  renderLegend();
  renderSegmentList();
  renderHealth();
  renderAll();
  centerAndFit();
  if (detailsId) showDetails(detailsId);
})();
